generated_pydough:
# Step 1: Identify people who are gymnasts and get their hometowns
gymnast_hometowns = peoples.WHERE(
    HAS(gymnasts) == 1
).CALCULATE(
    hometown=hometown
)

# Step 2: Group by hometown, count gymnasts, and find the most common one
most_common_hometown = gymnast_hometowns.PARTITION(
    name="hometown_groups",
    by=hometown
).CALCULATE(
    hometown=hometown,
    n_gymnasts=COUNT(gymnast_hometowns)
).TOP_K(1, by=n_gymnasts.DESC()).CALCULATE(
    hometown=hometown
)

most_common_amenity = has_amenities.CALCULATE(
    amenity_name=dorm_amenity.amenity_name
).PARTITION(
    name="amenity_groups",
    by=amenity_name
).CALCULATE(
    amenity_name=amenity_name,
    total_count=COUNT(has_amenities)
).TOP_K(1, by=total_count.DESC())

characteristic_counts = product_characteristic.CALCULATE(
    char_name=characteristic.characteristic_name
).PARTITION(
    name="char_groups", by=(char_name)
).CALCULATE(
    characteristic_name=char_name,
    count_of_products=COUNT(product_characteristic)
).TOP_K(1, by=count_of_products.DESC()).CALCULATE(
    characteristic_name=characteristic_name
)
